def blocks_comps(squares):
    s=set(squares); comps=[]; seen=set()
    for p in sorted(s):
        if p in seen: continue
        st=[p]; comp={p}
        while st:
            y,x=st.pop()
            # neighbors: any square overlapping/touching the current 2x2 block (shares cell or edge adjacent)
            for q in list(s)-comp:
                ry,rx=q
                # does block p touch block q? distance <=1
                if max(abs(y-ry),abs(x-rx))<=1:
                    comp.add(q); st.append(q)
        seen|=comp; comps.append(comp)
    return comps
